database.function('mashiro_governance_before', { varargs: true }, (...args) => {
  const [table, ...keys] = args
  const watch = typeof table === 'string' ? names.get(table) : undefined
  if (!watch || keys.length !== watch.keys.length) throw Error('GOVERNANCE_INVALID_EVENT')
  dirty = true
  const token = observer.before(String(table), keys)
  if (!token || token.length > 200) throw Error('GOVERNANCE_INVALID_TOKEN')
  return token
})
for (const watch of watches)
  for (const action of ['INSERT', 'UPDATE', 'DELETE']) {
    const row = action === 'DELETE' ? 'OLD' : 'NEW'
    database.exec(`CREATE TEMP TRIGGER mashiro_governance_${watch.table}_${action}
      BEFORE ${action} ON main.${watch.table}
      BEGIN INSERT INTO production_governance_commits(token) VALUES(mashiro_governance_before('${watch.table}',${watch.keys.map((key) => row + '.' + key).join(',')})); END`)
  }
database.function('mashiro_governance_before', { varargs: true }, (...args) => {
  const [table, deleted, ...data] = args
  const watch = typeof table === 'string' ? names.get(table) : undefined
  if (!watch || ![0, 1].includes(Number(deleted)) || data.length !== watch.keys.length + (watch.values?.length ?? 0))
    throw Error('GOVERNANCE_INVALID_EVENT')
  dirty = true
  const token = observer.before(String(table), data.slice(0, watch.keys.length), data.slice(watch.keys.length), deleted === 1)
  if (!token || token.length > 200) throw Error('GOVERNANCE_INVALID_TOKEN')
  return token
})
for (const watch of watches) {
  const expression = (row: string, value: { column: string; json?: string }) => value.json
    ? "json_extract(" + row + '.' + value.column + ",'$." + value.json + "')"
    : row + '.' + value.column
  for (const value of watch.values ?? [])
    if (!/^[a-z_]+$/.test(value.column) || (value.json !== undefined && !/^[A-Za-z_]+$/.test(value.json)))
      throw Error('GOVERNANCE_INVALID_PROJECTION')
  const insertion = (row: string, deleted: boolean, condition = '') =>
    "INSERT INTO production_governance_commits(token) SELECT mashiro_governance_before('" + watch.table + "'," + Number(deleted) + ',' +
    [...watch.keys.map((key) => row + '.' + key), ...(watch.values ?? []).map((value) => expression(row, value))].join(',') + ')' + condition + ';'
  for (const action of ['INSERT', 'UPDATE', 'DELETE']) {
    const row = action === 'DELETE' ? 'OLD' : 'NEW'
    const oldKey = action === 'UPDATE' ? insertion('OLD', true, ' WHERE ' + watch.keys.map((key) => 'OLD.' + key + ' IS NOT NEW.' + key).join(' OR ')) : ''
    database.exec('CREATE TEMP TRIGGER mashiro_governance_' + watch.table + '_' + action + ' BEFORE ' + action + ' ON main.' + watch.table + ' BEGIN ' + oldKey + insertion(row, action === 'DELETE') + ' END')
  }
}
